// The bundles carried up to the lighthouse steps (`bundles` "steps"): two heaps on the lowest step and a third, the one
// that fell in the sea, dark and wet beside them, a puddle round it.
if (e.state.bundles === "steps") {
  e.lib.bundle(g, -0.55, 0.8, 0.4, false);
  e.lib.bundle(g, 0.25, 0.7, 0.36, false);
  e.lib.bundle(g, 0.95, 0.75, 0.34, true);
}
